"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1395],{46701:e=>{e.exports=JSON.parse('{"functions":[{"name":"ToStack","desc":"Build one stack from one rolled set.\\n\\nReturns nil when the ClassName does not resolve. Durability is applied as a\\npercentage of the item\'s own maximum; a set that names no durability gets\\nthe item\'s default.","params":[{"name":"item_set","desc":"","lua_type":"ItemSet"}],"returns":[{"desc":"","lua_type":"ItemStack?\\n"}],"function_type":"method","source":{"line":97,"path":"src2/server/EmberServerLibrary/GameServer/Services/ItemSpawnService.service.luau"}},{"name":"ToStacks","desc":"Flatten a rolled tree into stacks, losing the nesting.\\n\\nFor callers that only want \\"what items did this produce\\" -- a preview, a\\ndrop table, `ContainerService.SpawnProvider`. Use `Fill` when the nesting\\nmatters.","params":[{"name":"item_sets","desc":"","lua_type":"{ ItemSet }"}],"returns":[{"desc":"","lua_type":"{ ItemStack }\\n"}],"function_type":"method","source":{"line":125,"path":"src2/server/EmberServerLibrary/GameServer/Services/ItemSpawnService.service.luau"}},{"name":"Fill","desc":"Place a rolled tree into an inventory, building nested inventories as needed.\\n\\nReturns what was placed and what was not, with a reason -- the original\\nwarned and carried on, so a loot table that had drifted out of date kept\\nspawning less than it claimed with nothing but console noise to show for it.","params":[{"name":"inventory","desc":"","lua_type":"Inventory"},{"name":"item_sets","desc":"","lua_type":"{ ItemSet }"}],"returns":[{"desc":"","lua_type":"FillResult\\n"}],"function_type":"method","source":{"line":149,"path":"src2/server/EmberServerLibrary/GameServer/Services/ItemSpawnService.service.luau"}},{"name":"FindHolder","desc":"The holder a just-placed stack of this kind ended up in.\\n\\nNesting has to attach to a holder, and `TransferToGroup` does not say which\\none it filled. Searching for the class afterwards is unambiguous in practice\\nbecause a nested spawn is a container item and containers do not stack.","params":[{"name":"inventory","desc":"","lua_type":"Inventory"},{"name":"stack","desc":"","lua_type":"ItemStack"}],"returns":[{"desc":"","lua_type":"ItemHolder?\\n"}],"function_type":"method","source":{"line":236,"path":"src2/server/EmberServerLibrary/GameServer/Services/ItemSpawnService.service.luau"}},{"name":"FindPlaced","desc":"","params":[{"name":"inventory","desc":"","lua_type":"Inventory"},{"name":"stack","desc":"","lua_type":"ItemStack"}],"returns":[{"desc":"","lua_type":"ItemStack?\\n"}],"function_type":"method","source":{"line":252,"path":"src2/server/EmberServerLibrary/GameServer/Services/ItemSpawnService.service.luau"}},{"name":"AttachChildInventory","desc":"Give a placed container item an inventory of its own.\\n\\nReturns nil when the item is not a container.","params":[{"name":"holder","desc":"","lua_type":"ItemHolder"},{"name":"stack","desc":"","lua_type":"ItemStack"}],"returns":[{"desc":"","lua_type":"Inventory?\\n"}],"function_type":"method","source":{"line":264,"path":"src2/server/EmberServerLibrary/GameServer/Services/ItemSpawnService.service.luau"}},{"name":"Spawn","desc":"Roll `spawn_data` and fill `inventory` from it, in one call.","params":[{"name":"inventory","desc":"","lua_type":"Inventory"},{"name":"spawn_data","desc":"","lua_type":"SpawnData"},{"name":"options","desc":"","lua_type":"RollOptions?\\n"}],"returns":[{"desc":"","lua_type":"FillResult\\n"}],"function_type":"method","source":{"line":295,"path":"src2/server/EmberServerLibrary/GameServer/Services/ItemSpawnService.service.luau"}},{"name":"ProviderFor","desc":"A `ContainerService.SpawnProvider` bound to a spawn table.\\n\\nThe provider contract is flat -- it hands back stacks and lets the container\\nplace them -- so nesting is lost through this path. A container whose loot\\nincludes containers should be filled with `Spawn` directly.","params":[{"name":"spawn_data","desc":"","lua_type":"SpawnData"},{"name":"options","desc":"","lua_type":"RollOptions?\\n"}],"returns":[{"desc":"","lua_type":"(any) -> { ItemStack }\\n"}],"function_type":"method","source":{"line":312,"path":"src2/server/EmberServerLibrary/GameServer/Services/ItemSpawnService.service.luau"}},{"name":"OwnedProvider","desc":"A provider for owners that carry their OWN spawn table.\\n\\n`ProviderFor` binds one table for every caller, which suits a container type\\nwhose loot is fixed. A ground spawner is the other case: each one references\\ndifferent spawn data, so the provider has to read it off the owner.\\n\\nWorks for anything shaped `{ SpawnData, State = { Randomness } }`, which is\\nboth `GroundSpawnerData` and `ContainerData`. An owner with no spawn data\\nyields nothing rather than erroring -- an unconfigured spawner is a normal\\nstate, not a fault.","params":[{"name":"options","desc":"","lua_type":"RollOptions?"}],"returns":[{"desc":"","lua_type":"(any) -> { ItemStack }\\n"}],"function_type":"method","source":{"line":346,"path":"src2/server/EmberServerLibrary/GameServer/Services/ItemSpawnService.service.luau"}}],"properties":[],"types":[],"name":"ItemSpawnService","desc":"Turns a rolled loot table into stacks that actually go somewhere.\\n\\n`ItemSpawnData` decides WHAT spawns and owns no items. This decides what that\\nbecomes: it resolves each `ItemSet`\'s ClassName through `ItemService`, builds\\nan `ItemStack`, and places it -- nesting included, so a crate can spawn with a\\nbackpack in it that has things in the backpack.\\n\\nWHAT CHANGED\\n\\n`spawnItemFromItemSet` constructed an item object per set, called\\n`SetQuantity` and `SetDurability` on it, and recursed into\\n`parent_item.InventoryManager:AddItem(child_item)`. Three things went wrong\\nthere and are gone here:\\n\\n  * `SetQuantity` clamps to the stack limit and destroys at zero, so a spawn\\n    table asking for more than a stack silently produced less and never said\\n    so. `Fill` returns what did not fit.\\n  * a child whose parent had no InventoryManager warned and then added it\\n    anyway, to nil. Nesting is explicit now and reports where it failed.\\n  * an unknown ClassName warned per occurrence, every respawn, forever.\\n    Unresolved sets come back in the result instead.\\n\\nDURABILITY IS A PERCENTAGE\\n\\n`ItemSet.Durability` is 0-100 and is multiplied by the item\'s own\\nMaxDurability. The original did that multiplication two functions away from\\nwhere the field was set, which is a good way to read it as absolute.","source":{"line":34,"path":"src2/server/EmberServerLibrary/GameServer/Services/ItemSpawnService.service.luau"}}')}}]);